func newNDetentionPolicyTier(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]detentionpolicy.DetentionPolicyTier, n)))
}

func ptrDetentionPolicyTier(p unsafe.Pointer, c int32) any {
	r := (*detentionpolicy.DetentionPolicyTier)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.DetentionPolicyID))
	case 4:
		return &r.FromMinute
	case 5:
		return &r.ToMinute
	case 6:
		return &r.Rate
	case 7:
		return (*string)(unsafe.Pointer(&r.RateUnit))
	case 8:
		return &r.Label
	case 9:
		return &r.SortOrder
	case 10:
		return &r.CreatedAt
	case 11:
		return &r.UpdatedAt
	}
	return nil
}

func valueDetentionPolicyTier(p unsafe.Pointer, c int32) any {
	r := (*detentionpolicy.DetentionPolicyTier)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.DetentionPolicyID)
	case 4:
		return r.FromMinute
	case 5:
		if r.ToMinute == nil {
			return nil
		}
		return *r.ToMinute
	case 6:
		return r.Rate
	case 7:
		return string(r.RateUnit)
	case 8:
		if r.Label == "" {
			return nil
		}
		return r.Label
	case 9:
		return r.SortOrder
	case 10:
		return r.CreatedAt
	case 11:
		return r.UpdatedAt
	}
	return nil
}

